<?php
require_auth(['student', 'ambassador']);
$pageTitle = 'Bài nộp của tôi';
$submissions = rows('SELECT s.*, c.title AS campaign_title, c.reward_points FROM submissions s JOIN campaigns c ON c.id = s.campaign_id WHERE s.user_id = ? ORDER BY s.id DESC', [user()['id']]);
?>
<div class="page-actions"><p class="page-intro">Theo dõi trạng thái duyệt và phản hồi từ đội ngũ Marketing.</p><a class="btn btn-brand" href="index.php?page=campaigns"><i class="bi bi-plus-lg"></i> Nộp bài mới</a></div>
<div class="row g-4"><?php foreach ($submissions as $submission): ?><div class="col-lg-6"><article class="submission-card"><div class="submission-thumb"><i class="bi bi-play-circle-fill"></i><span><?= e($submission['status']) ?></span></div><div class="submission-content"><span class="badge text-bg-<?= e(status_badge($submission['status'])) ?>-subtle"><?= e($submission['status']) ?></span><h3><?= e($submission['campaign_title']) ?></h3><p><?= e($submission['caption']) ?></p><div class="submission-meta"><span><i class="bi bi-calendar3"></i> <?= date('d/m/Y', strtotime($submission['submitted_at'])) ?></span><strong><i class="bi bi-gift-fill"></i> <?= (int) $submission['reward_points'] ?> điểm</strong></div><?php if ($submission['feedback']): ?><div class="feedback-box"><i class="bi bi-chat-quote-fill"></i><p><strong>Phản hồi từ CMC</strong><?= e($submission['feedback']) ?></p></div><?php endif; ?><a class="btn btn-light border w-100" href="<?= e($submission['content_url']) ?>" target="_blank">Xem nội dung <i class="bi bi-box-arrow-up-right"></i></a></div></article></div><?php endforeach; ?><?php if (!$submissions): ?><div class="col-12"><div class="empty-state"><i class="bi bi-camera-reels"></i><h2>Chưa có bài nộp</h2><p>Chọn một nhiệm vụ phù hợp và bắt đầu kể câu chuyện của bạn.</p><a class="btn btn-brand" href="index.php?page=campaigns">Khám phá nhiệm vụ</a></div></div><?php endif; ?></div>
